root=Path(__file__).resolve().parents[2];tag=sys.argv[1];out=root/'_local/act4-perf';out.mkdir(parents=True,exist_ok=True);f=json.loads((root/'tests/fixtures/act4-rc/support-entry-fixture.json').read_text())['profile'];f['cleared']={str(i):{'visits':1,'rounds':5,'stars':1,'shots':0} for i in range(1,40)};f.update(lastStage=40,mapNode=40);f.pop('honroBattle',None)
