 data=p.evaluate("""()=>{const a=HonroApp,e=a.engine,b=e.b,u=e.active,C=HONRO_CORE,results=[];const original=structuredClone(b);const scenarios=['official','modified-art','custom-map','broken-terrain','status-effects'];for(const scenario of scenarios){delete b.honroCustom;delete b.honroMapOrigin;delete b.qaAlias;Object.assign(b,structuredClone(original));e.invalidateTerrainCollisionIndex();const actor=e.active;if(scenario==='modified-art'){const asset=b.honroLandmarks.find(l=>l.asset?.vector)?.asset;if(asset){asset.vector.__qaChanged={text:'modified',nested:[1,2,3]};asset.collision=[{x:5,y:9,w:13,h:17}];}}if(scenario==='custom-map'){b.honroCustom=true;b.honroMapOrigin='workshop';}if(scenario==='broken-terrain'){if(b.terrain[1])b.terrain[1].broken=true;b.sceneVersion++;}if(scenario==='status-effects'){actor.slowed={factor:.4,expires:8};actor.shield=33;actor.curseTurns=2;actor.curseDamage=7;actor.focus=actor.maxFocus;const enemy=b.units.find(v=>v.side===1);if(enemy){enemy.curseTurns=3;enemy.shield=19;}}for(const s of Object.values(C.SKILLS).filter(s=>!s.passive)){actor.cls=s.cls;actor.loadout=[s.id];actor.ranks[s.id]=3;actor.angle=44;actor.acted=false;actor.retreat=false;actor.dead=false;const before=JSON.stringify(b),rng=b.rng;let output;try{output={prediction:e.predict(actor,s,44,.6,undefined,true,false)}}catch(err){output={error:String(err)}}const after=JSON.stringify(b);results.push({scenario,id:s.id,output,unchanged:before===after,rngBefore:rng,rngAfter:b.rng});if(before!==after)throw Error('Prediction mutated live battle '+scenario+' '+s.id)}}return {results,stage:b.honroStage};}""")
